'use client';
import React,{useState,useEffect,useRef} from 'react';
import {LayoutGrid,Store as StoreIcon,Package,Users,ShoppingBag,MessageCircle,Bot,Plug,Settings,ArrowUpRight,Plus,ChevronDown,ArrowRight,Search,MoreHorizontal,Check,CheckCircle2,Download,X,ChevronRight,Sparkles,Globe,Camera,Send,ShieldCheck,Menu,RefreshCw,Tag,Wallet,BookOpen,SlidersHorizontal,LifeBuoy,Layers,TriangleAlert,Link2} from 'lucide-react';
import {simulateReply,type Workspace,type Store,type Entry,type Agent} from '../lib/domain';
import {SalesActivity, OperationsRail} from './glass-widgets';
type Page='overview'|'stores'|'dashboard'|'products'|'contacts'|'orders'|'agent'|'channels'|'conversations'|'promotions'|'integrations'|'metrics'|'settings';
type Modal={kind:string;data?:any}|null;
const money=(n:number)=>new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(n);
const date=(v:string)=>new Date(v).toLocaleDateString('es-PE',{day:'2-digit',month:'short'});
const initials=(s:string)=>s.trim().split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();
const names:Record<Page,string>={overview:'Vista general',stores:'Mis tiendas',dashboard:'Inicio de tienda',products:'Productos',contacts:'Clientes',orders:'Pedidos',agent:'Vendedor',channels:'Canales',conversations:'Conversaciones',promotions:'Promociones',integrations:'Integraciones',metrics:'Métricas',settings:'Configuración'};
const channels=[{name:'WhatsApp',icon:MessageCircle,color:'green',description:'Atiende consultas y recibe pedidos desde tu número de negocio.',needs:'Requiere WhatsApp Business Platform, credenciales y un webhook para recibir mensajes.'},{name:'Instagram',icon:Camera,color:'plum',description:'Gestiona mensajes directos y consultas de tu comunidad.',needs:'Requiere una cuenta profesional de Instagram, permisos y la integración con Meta.'},{name:'Messenger',icon:MessageCircle,color:'blue',description:'Reúne las consultas de tu página de Facebook.',needs:'Requiere conectar tu página y habilitar los permisos de mensajería de Meta.'},{name:'Chat web',icon:Globe,color:'orange',description:'Un vendedor para las personas que visitan tu página.',needs:'Requiere publicar e integrar un widget y conectar un motor de respuestas.'}];
const nav=[{id:'dashboard',name:'Inicio',icon:LayoutGrid},{id:'products',name:'Productos',icon:Package},{id:'promotions',name:'Promociones',icon:Tag},{id:'agent',name:'Vendedor',icon:Bot},{id:'channels',name:'Canales',icon:Plug},{id:'integrations',name:'Integraciones',icon:Layers},{id:'contacts',name:'Clientes',icon:Users},{id:'conversations',name:'Conversaciones',icon:MessageCircle},{id:'orders',name:'Pedidos',icon:ShoppingBag},{id:'metrics',name:'Métricas',icon:SlidersHorizontal}] as const;
function Badge({children,tone='neutral'}:{children:React.ReactNode;tone?:string}){return <span className={'badge '+tone}>{children}</span>}
function Empty({icon:Icon=Package,title,body,action,label}:{icon?:any;title:string;body:string;action?:()=>void;label?:string}){return <div className="empty"><div className="empty-icon"><Icon size={26}/></div><h3>{title}</h3><p>{body}</p>{action&&<button className="btn primary" onClick={action}><Plus size={16}/>{label}</button>}</div>}
export default function WorkspaceApp({userName}:{userName:string}){
 const [workspace,setWorkspace]=useState<Workspace>({stores:[]});const [version,setVersion]=useState(0);const [loading,setLoading]=useState(true);const [failure,setFailure]=useState('');const [busy,setBusy]=useState(false);const busyRef=useRef(false);
 const [selected,setSelected]=useState<string|null>(null);const [page,setPage]=useState<Page>('overview');const [modal,setModal]=useState<Modal>(null);const [notice,setNotice]=useState('');const [search,setSearch]=useState('');const [statusFilter,setStatusFilter]=useState('Todos');const [menuOpen,setMenuOpen]=useState(false);const [storeDropdown,setStoreDropdown]=useState(false);const [tab,setTab]=useState('personalidad');const [mobile,setMobile]=useState(false);
 const [navExpanded,setNavExpanded]=useState(false);const [solidMode,setSolidMode]=useState(false);
 useEffect(()=>{setSolidMode(localStorage.getItem('nexo-solid-mode')==='1');},[]);
 function requestNewStore(){if(workspace.stores.length>=5){setNotice('Ya tienes 5 tiendas: alcanzaste el límite de este espacio.');return;}setModal({kind:'store'});}
 function toggleSurface(){setSolidMode(v=>{localStorage.setItem('nexo-solid-mode',v?'0':'1');return !v;});}
 const [chat,setChat]=useState<{role:string;text:string}[]>([]);const [message,setMessage]=useState('');
 const store=workspace.stores.find(s=>s.id===selected)||null;
 const allStores=workspace.stores;const actual=allStores.filter(s=>!s.demo);const scope=store?[store]:allStores;const allOrders=scope.flatMap(s=>s.orders.map(o=>({...o,storeName:s.name,storeId:s.id})));const orders=allOrders.filter(o=>o.status!=='Cancelado');const sales=orders.filter(o=>o.paymentStatus==='Pagado').reduce((a,o)=>a+o.total,0);const clients=scope.reduce((a,s)=>a+s.contacts.length,0);const productCount=scope.reduce((a,s)=>a+s.products.filter(p=>p.active).length,0);
 async function load(){setLoading(true);setFailure('');try{const r=await fetch('/api/workspace',{cache:'no-store'});const d:any=await r.json();if(!r.ok)throw new Error(d.error||'No se pudo cargar.');setWorkspace(d.workspace);setVersion(d.version);}catch(e){setFailure((e as Error).message);}finally{setLoading(false);}}
 useEffect(()=>{load();},[]);useEffect(()=>{if(!notice)return;const t=setTimeout(()=>setNotice(''),5000);return()=>clearTimeout(t);},[notice]);
 useEffect(()=>{setSearch('');setStatusFilter('Todos');setChat([]);},[page,selected]);
 useEffect(()=>{function key(e:KeyboardEvent){if(e.key==='Escape'){setModal(null);setStoreDropdown(false);setMobile(false);}if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();setMenuOpen(v=>!v);}}window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key);},[]);
 async function mutate(type:string,payload:any,success='Cambios guardados'){
  if(busyRef.current)return false;busyRef.current=true;setBusy(true);
  try{const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type,payload,version})});const d:any=await r.json();if(!r.ok)throw new Error(d.error||'No se pudo guardar.');setWorkspace(d.workspace);setVersion(d.version);setNotice(success);return d.workspace as Workspace;}catch(e){setNotice((e as Error).message);return false;}finally{busyRef.current=false;setBusy(false);}
 }
 function go(p:Page){setPage(p);setModal(null);setMobile(false);setMenuOpen(false);}
 function openStore(id:string,p:Page='dashboard'){setSelected(id);setStoreDropdown(false);go(p);}
 function exportData(){const data=store?{exportedAt:new Date().toISOString(),stores:[store]}:{exportedAt:new Date().toISOString(),stores:allStores};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=store?'nexo-tienda.json':'nexo-mis-tiendas.json';a.click();URL.revokeObjectURL(url);setNotice('Exportación descargada.');}
 const statusTone=(s:string)=>s==='Entregado'||s==='Pagado'?'green':s==='Cancelado'||s==='Inactivo'?'neutral':s==='Pendiente'?'orange':'plum';
 function storeRequired(content:()=>React.ReactNode){return store?content():<Empty icon={StoreIcon} title="Elige una tienda para continuar" body="Cada tienda tiene sus propios productos, clientes, pedidos y vendedor." action={()=>go('stores')} label="Ver mis tiendas"/>;}
 function Heading({title,body,action,label,icon:Icon=Plus}:{title:string;body:string;action?:()=>void;label?:string;icon?:any}){return <div className="section-heading"><div><h1>{title}</h1><p>{body}</p></div>{action&&<button className="btn primary" onClick={action}><Icon size={17}/>{label}</button>}</div>}
 function metricsCards(){return <div className="stats-grid">{[{label:'Ventas cobradas',value:money(sales),icon:Wallet,detail:'Pedidos pagados, sin cancelados',tone:'plum'},{label:'Pedidos registrados',value:String(allOrders.length),icon:ShoppingBag,detail:`${orders.filter(o=>o.status==='Pendiente').length} pendientes por confirmar`,tone:'orange'},{label:'Clientes',value:String(clients),icon:Users,detail:store?'Contactos de esta tienda':'Contactos en todas tus tiendas',tone:'green'},{label:'Productos activos',value:String(productCount),icon:Package,detail:store?'Disponibles en tu catálogo':`${allStores.length} tiendas en tu espacio`,tone:'blue'}].map(x=><div className="stat" key={x.label}><div className="stat-label">{x.label}<span className={'icon-tile '+x.tone}><x.icon size={16}/></span></div><strong>{x.value}</strong><small>{x.detail}</small></div>)}</div>}
 function storeCard(s:Store){const so=s.orders.filter(o=>o.status!=='Cancelado');return <article className="store-card" key={s.id}><div className="store-card-top"><span className={'store-avatar '+s.color}>{initials(s.name)}</span><Badge tone={s.demo?'orange':'green'}>{s.demo?'Ejemplo':'Mi tienda'}</Badge><button className="icon-button push" title={'Editar '+s.name} onClick={()=>setModal({kind:'store',data:s})}><MoreHorizontal size={20}/></button></div><h3>{s.name}</h3><p>{s.category}</p><div className="store-numbers"><div><strong>{money(so.filter(o=>o.paymentStatus==='Pagado').reduce((a,o)=>a+o.total,0))}</strong><small>Cobrado</small></div><div><strong>{s.products.length}</strong><small>Productos</small></div><div><strong>{s.orders.length}</strong><small>Pedidos</small></div></div><div className="store-card-foot"><span className="dot-status"><i/>Canales pendientes</span><button className="text-button" onClick={()=>openStore(s.id)}>Gestionar <ArrowUpRight size={16}/></button></div></article>;}
 function recentOrders(){return <div className="panel"><div className="panel-title"><div><h3>Últimos pedidos</h3><p>La actividad más reciente de tus tiendas.</p></div><button className="text-button" onClick={()=>go('orders')}>Ver pedidos <ArrowRight size={15}/></button></div>{allOrders.length?<div className="table-wrap"><table><thead><tr><th>Pedido / cliente</th>{!store&&<th>Tienda</th>}<th>Total</th><th>Estado</th></tr></thead><tbody>{[...allOrders].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,5).map(o=><tr key={o.id}><td><button className="cell-button" onClick={()=>{if(!store)setSelected(o.storeId);setModal({kind:'orderDetail',data:{...o,storeId:o.storeId}});}}>{o.number}<small>{o.customer}</small></button></td>{!store&&<td>{o.storeName}</td>}<td>{money(o.total)}</td><td><Badge tone={statusTone(o.status)}>{o.status}</Badge></td></tr>)}</tbody></table></div>:<div className="mini-empty"><ShoppingBag size={28}/><h4>Tus próximos pedidos aparecerán aquí</h4><p>Registra una venta para empezar a medir tu negocio.</p></div>}</div>}
 function overview(){return <><div className="eyebrow">TU CENTRO DE OPERACIONES</div><Heading title={`Hola, ${userName.split(' ')[0]} ✨`} body="Un buen día para hacer crecer tus tiendas." action={()=>requestNewStore()} label="Nueva tienda"/>{allStores.some(s=>s.demo)&&<div className="inline-note orange"><TriangleAlert size={17}/>Las tiendas marcadas como «Ejemplo» contienen datos ficticios y están incluidas en este resumen.</div>}{metricsCards()}<div className="activity-grid"><SalesActivity orders={allOrders}/><div className="focus-card"><span className="focus-icon"><StoreIcon size={30}/></span><Badge tone="light">TU ESPACIO MULTITIENDA</Badge><h2>Todo empieza<br/>con una idea.</h2><p>Crea un espacio para cada marca y mantén el control de todas.</p><button className="btn primary" onClick={()=>requestNewStore()}>{allStores.length?'Añadir tienda':'Crear mi primera tienda'}<ArrowUpRight size={16}/></button></div></div><div className="section-subtitle"><h2>Mis tiendas <span className="count">{allStores.length}</span></h2><button className="text-button" onClick={()=>go('stores')}>Ver todas <ArrowRight size={16}/></button></div>{allStores.length?<div className="store-grid">{allStores.slice(0,3).map(storeCard)}</div>:<div className="start-grid"><div className="start-card"><span className="step-number">01</span><h3>Crea tu primera tienda</h3><p>Elige un nombre y una categoría. Puedes gestionar hasta cinco tiendas en este espacio.</p><button className="text-button" onClick={()=>requestNewStore()}>Crear tienda <ArrowRight size={16}/></button></div><div className="start-card"><span className="step-number">02</span><h3>Prepara tu catálogo</h3><p>Organiza productos, precios y stock de forma independiente para cada marca.</p><span className="muted small">Después de crear una tienda</span></div><div className="start-card"><span className="step-number">03</span><h3>Explora con ejemplos</h3><p>Prueba el sistema con tres tiendas ficticias antes de empezar con tus datos.</p><button className="text-button" disabled={busy} onClick={()=>mutate('demo.load',{},'Tres tiendas de ejemplo creadas.')}>Cargar ejemplos <ArrowRight size={16}/></button></div></div>}<div className="two-column">{recentOrders()}<div className="panel checklist"><div className="panel-title"><h3>Tu siguiente paso</h3><span className="icon-tile plum"><Sparkles size={16}/></span></div>{[{title:'Crear tus tiendas',body:`${actual.length} tiendas propias creadas`,done:actual.length>0,fn:()=>go('stores')},{title:'Completar el catálogo',body:'Productos, precios y disponibilidad',done:productCount>0,fn:()=>{if(allStores.length)openStore(allStores[0].id,'products');else requestNewStore();}},{title:'Configurar el vendedor',body:'Personalidad y políticas por tienda',done:allStores.some(s=>s.agent.description),fn:()=>{if(allStores.length)openStore(allStores[0].id,'agent');else requestNewStore();}},{title:'Conectar canales',body:'Pendiente de integración externa',done:false,fn:()=>go('channels')}].map((x,i)=><button className="checklist-row" onClick={x.fn} key={x.title}><span className={'check-circle '+(x.done?'done':'')}>{x.done?<Check size={12}/>:i+1}</span><span><b>{x.title}</b><small>{x.body}</small></span><ChevronRight size={16}/></button>)}</div></div></>;}
 function storesPage(){return <><Heading title="Un espacio para cada marca" body="Gestiona todas tus tiendas sin mezclar productos, clientes ni pedidos." action={()=>requestNewStore()} label="Nueva tienda"/><div className="toolbar"><label className="search-field"><Search size={17}/><input placeholder="Buscar una tienda…" value={search} onChange={e=>setSearch(e.target.value)}/></label><span className="muted small">{allStores.length} / 5 tiendas · moneda S/ PEN</span></div>{allStores.length?<div className="store-grid">{allStores.filter(s=>(s.name+' '+s.category).toLowerCase().includes(search.toLowerCase())).map(storeCard)}</div>:<Empty icon={StoreIcon} title="Aquí comienza tu próxima tienda" body="Crea un espacio independiente para cada negocio y gestiónalos todos desde Nexo." action={()=>requestNewStore()} label="Crear mi primera tienda"/>}</>;}
 function dashboard(){return storeRequired(()=>{const s=store!;const steps=[{title:'Tu negocio',text:'Define la identidad y los datos de tu marca.',icon:StoreIcon,done:!!s.agent.description,page:'agent'},{title:'Tu catálogo',text:'Agrega productos, precios y stock disponible.',icon:Package,done:s.products.length>0,page:'products'},{title:'Tu vendedor',text:'Prepara mensajes, políticas y preguntas frecuentes.',icon:Bot,done:s.faqs.length>0||!!s.agent.shipping,page:'agent'},{title:'Tus canales',text:'Revisa las conexiones necesarias para vender.',icon:Plug,done:false,page:'channels'}];return <><div className="eyebrow">ESPACIO DE TIENDA {s.demo?'· DATOS DE EJEMPLO':''}</div><Heading title={s.name} body="Tu catálogo, tus clientes y tus ventas. Todo en su lugar." action={()=>setModal({kind:'order'})} label="Registrar pedido"/>{metricsCards()}<div className="panel setup-panel"><div className="panel-title"><div><h2>Preparemos tu tienda</h2><p>Completa la configuración y deja todo listo para tus ventas.</p></div><Badge tone="plum">{steps.filter(s=>s.done).length} de 4 pasos</Badge></div><div className="setup-grid">{steps.map((st,i)=><button className="setup-card" onClick={()=>go(st.page as Page)} key={st.title}><span className={'icon-tile '+(st.done?'green':'plum')}><st.icon size={22}/></span><small>PASO {i+1}</small><h3>{st.title}</h3><p>{st.text}</p><span className="text-button">{st.done?'Revisar':'Configurar'} <ArrowRight size={15}/></span></button>)}</div></div><div className="two-column">{recentOrders()}<div className="panel"><div className="panel-title"><h3>Tu vendedor de prueba</h3><Bot size={22}/></div><div className="agent-preview"><span className="agent-avatar"><Bot size={32}/></span><h3>{s.agent.name}</h3><Badge tone="orange">Motor de IA pendiente</Badge><p>Prueba respuestas del catálogo y las preguntas frecuentes sin enviar mensajes a clientes.</p><button className="btn secondary" onClick={()=>setModal({kind:'test'})}>Probar respuestas <ArrowUpRight size={15}/></button></div></div></div></>});}
 function productsPage(){return storeRequired(()=>{const s=store!;const list=s.products.filter(p=>(p.name+' '+p.sku+' '+p.category).toLowerCase().includes(search.toLowerCase())&&(statusFilter==='Todos'||(statusFilter==='Activos'?p.active:!p.active)));return <><Heading title="Tu catálogo, siempre al día" body={`Productos de ${s.name}. Los cambios solo afectan a esta tienda.`} action={()=>setModal({kind:'product'})} label="Añadir producto"/><div className="toolbar"><label className="search-field"><Search size={17}/><input placeholder="Buscar por nombre, SKU o categoría…" value={search} onChange={e=>setSearch(e.target.value)}/></label><select aria-label="Filtrar productos" value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option>Todos</option><option>Activos</option><option>Archivados</option></select><span className="muted small">{list.length} productos</span></div><div className="panel">{list.length?<div className="table-wrap"><table><thead><tr><th>Producto</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Estado</th><th/></tr></thead><tbody>{list.map(p=><tr key={p.id}><td><div className="product-cell"><span className={'product-placeholder '+s.color}><Package size={22}/></span><span><b>{p.name}</b><small>{p.sku||'Sin SKU'}</small></span></div></td><td>{p.category||'—'}</td><td><b>{money(p.price)}</b></td><td><Badge tone={p.stock===0?'orange':p.stock<6?'orange':'neutral'}>{p.stock} unidades</Badge></td><td><Badge tone={p.active?'green':'neutral'}>{p.active?'Activo':'Archivado'}</Badge></td><td><button className="text-button" onClick={()=>setModal({kind:'product',data:p})}>Editar</button></td></tr>)}</tbody></table></div>:<Empty title={search?'No encontramos productos':'Tu primer producto te espera'} body="Añade nombre, precio y stock. Puedes editar o archivar los productos cuando lo necesites." action={()=>setModal({kind:'product'})} label="Añadir producto"/>}</div></>});}
 function contactsPage(){return storeRequired(()=>{const list=store!.contacts.filter(c=>(c.name+' '+c.phone+' '+c.email).toLowerCase().includes(search.toLowerCase())&&(statusFilter==='Todos'||c.stage===statusFilter));return <><Heading title="Conoce a tus clientes" body={`Contactos y seguimiento comercial de ${store!.name}.`} action={()=>setModal({kind:'contact'})} label="Nuevo cliente"/><div className="toolbar"><label className="search-field"><Search size={17}/><input placeholder="Buscar nombre, teléfono o email…" value={search} onChange={e=>setSearch(e.target.value)}/></label><select value={statusFilter} aria-label="Filtrar clientes" onChange={e=>setStatusFilter(e.target.value)}>{['Todos','Nuevo','En conversación','Cliente','Inactivo'].map(s=><option key={s}>{s}</option>)}</select></div><div className="panel">{list.length?<div className="table-wrap"><table><thead><tr><th>Cliente</th><th>Teléfono</th><th>Estado</th><th>Pedidos</th><th/></tr></thead><tbody>{list.map(c=><tr key={c.id}><td><div className="product-cell"><span className="contact-avatar">{initials(c.name)}</span><span><b>{c.name}</b><small>{c.email||'Sin email'}</small></span></div></td><td>{c.phone||'—'}</td><td><Badge tone={c.stage==='Cliente'?'green':'plum'}>{c.stage}</Badge></td><td>{store!.orders.filter(o=>o.contactId===c.id).length}</td><td><button className="text-button" onClick={()=>setModal({kind:'contact',data:c})}>Ver ficha</button></td></tr>)}</tbody></table></div>:<Empty icon={Users} title="Cada relación empieza con un contacto" body="Guarda los datos y notas de tus clientes para darles un mejor seguimiento." action={()=>setModal({kind:'contact'})} label="Nuevo cliente"/>}</div></>});}
 function ordersPage(){const list=allOrders.filter(o=>(o.number+' '+o.customer+' '+o.storeName).toLowerCase().includes(search.toLowerCase())&&(statusFilter==='Todos'||o.status===statusFilter));return <><Heading title="Cada pedido, bajo control" body={store?`Pedidos de ${store.name}. El stock se actualiza al registrar una venta.`:'Pedidos de todas tus tiendas, reunidos en una sola vista.'} action={store?()=>setModal({kind:'order'}):undefined} label="Registrar pedido"/><div className="toolbar"><label className="search-field"><Search size={17}/><input placeholder="Buscar pedido o cliente…" value={search} onChange={e=>setSearch(e.target.value)}/></label><select aria-label="Filtrar pedidos" value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}>{['Todos','Pendiente','Confirmado','Enviado','Entregado','Cancelado'].map(s=><option key={s}>{s}</option>)}</select></div><div className="panel">{list.length?<div className="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th>{!store&&<th>Tienda</th>}<th>Fecha</th><th>Total</th><th>Estado</th><th>Pago</th><th/></tr></thead><tbody>{list.map(o=><tr key={o.id}><td><b>{o.number}</b><small>{o.channel}</small></td><td>{o.customer}</td>{!store&&<td>{o.storeName}</td>}<td>{date(o.createdAt)}</td><td>{money(o.total)}</td><td><Badge tone={statusTone(o.status)}>{o.status}</Badge></td><td><Badge tone={statusTone(o.paymentStatus)}>{o.paymentStatus}</Badge></td><td><button className="text-button" onClick={()=>setModal({kind:'orderDetail',data:o})}>Ver</button></td></tr>)}</tbody></table></div>:<Empty icon={ShoppingBag} title="Todo listo para tu próxima venta" body={store?'Añade al menos un producto y un cliente para registrar tu primer pedido.':'Selecciona una tienda para registrar su primer pedido.'} action={()=>store?setModal({kind:'order'}):go('stores')} label={store?'Registrar pedido':'Elegir tienda'}/>}</div></>;}
 function agentPage(){return storeRequired(()=>{const s=store!;const tabs=[['personalidad','Personalidad'],['negocio','Mi negocio'],['politicas','Envíos y pagos'],['faq','Preguntas frecuentes'],['reglas','Flujos y reglas']];return <><Heading title="Un vendedor que conoce tu marca" body={`Configura cómo debe atender el vendedor de ${s.name}.`} action={()=>setModal({kind:'test'})} label="Probar respuestas" icon={MessageCircle}/><div className="tabs">{tabs.map(([v,n])=><button key={v} className={tab===v?'active':''} onClick={()=>setTab(v)}>{n}</button>)}</div><div className="inline-note"><Bot size={17}/>La configuración se guarda. Para responder automáticamente a clientes falta conectar un modelo de IA y un canal.</div>{['personalidad','negocio','politicas'].includes(tab)?<AgentForm key={s.id+tab} store={s} tab={tab} busy={busy} onSave={async a=>{await mutate('agent.save',{storeId:s.id,...a});}}/>:entryList(tab==='faq'?'faq':'rule',tab==='faq'?s.faqs:s.rules)}</>});}
 function entryList(kind:string,items:Entry[]){return <div className="panel"><div className="panel-title"><div><h3>{kind==='faq'?'Respuestas que tu vendedor debe conocer':kind==='rule'?'Reglas de atención':'Promociones de la tienda'}</h3><p>{kind==='rule'?'Estas instrucciones quedan preparadas para el futuro motor de IA.':kind==='promotion'?'Registro informativo. Los descuentos no se aplican automáticamente a los pedidos.':'Estas respuestas están disponibles en el probador por coincidencias.'}</p></div><button className="btn secondary" onClick={()=>setModal({kind})}><Plus size={16}/>Añadir</button></div>{items.length?<div className="entry-list">{items.map(x=><button className="entry-row" key={x.id} onClick={()=>setModal({kind,data:x})}><span className="icon-tile plum">{kind==='faq'?<BookOpen size={18}/>:kind==='rule'?<Layers size={18}/>:<Tag size={18}/>}</span><span><b>{x.title}</b><p>{x.content}</p></span><Badge tone={x.active?'green':'neutral'}>{x.active?'Activo':'Inactivo'}</Badge><ChevronRight size={16}/></button>)}</div>:<Empty icon={kind==='rule'?Layers:kind==='promotion'?Tag:BookOpen} title={kind==='rule'?'Define cómo se debe atender':kind==='promotion'?'Prepara tu próxima promoción':'Responde una vez, reutiliza después'} body="Añade información específica de esta tienda para mantener una atención consistente." action={()=>setModal({kind})} label="Añadir"/>}</div>;}
 function channelsPage(){return <><Heading title="Cada canal, una nueva oportunidad" body="Prepara los puntos de contacto de cada tienda. Las conexiones externas aún no están activadas."/><div className="inline-note orange"><Plug size={17}/>Sin canales conectados. Esta versión no recibe ni envía mensajes reales.</div><div className="channel-grid">{channels.map(c=><div className="panel channel-card" key={c.name}><div className="channel-top"><span className={'channel-icon '+c.color}><c.icon size={25}/></span><Badge>Pendiente</Badge></div><h3>{c.name}</h3><p>{c.description}</p><button className="btn secondary" onClick={()=>setModal({kind:'channel',data:c})}>Ver requisitos <ArrowUpRight size={15}/></button></div>)}</div><div className="panel connection-note"><ShieldCheck size={26}/><div><h3>Una conexión independiente por tienda</h3><p>Cada marca utilizará sus propias cuentas y credenciales. La conexión se incorporará después de elegir el canal y preparar el acceso del negocio.</p></div></div></>;}
 function integrationsPage(){return <><Heading title="Construye tu ecosistema" body="Elige las integraciones que necesitas. Ninguna conexión está activada todavía."/><div className="channel-grid">{[{name:'Modelo de IA',desc:'Respuestas abiertas basadas en tu catálogo e instrucciones.',icon:Bot},{name:'Catálogo externo',desc:'Sincronización de productos desde Shopify u otro sistema.',icon:Package},{name:'Pagos',desc:'Confirmaciones de pago desde un proveedor verificado.',icon:Wallet},{name:'Automatizaciones',desc:'Conexiones con flujos y herramientas de tu negocio.',icon:Layers}].map((x,i)=><div className="panel channel-card" key={x.name}><div className="channel-top"><span className={'channel-icon '+['plum','green','blue','orange'][i]}><x.icon size={25}/></span><Badge>Pendiente</Badge></div><h3>{x.name}</h3><p>{x.desc}</p><button className="text-button" onClick={()=>setModal({kind:'integration',data:x})}>Ver siguiente paso <ArrowRight size={16}/></button></div>)}</div></>;}
 function metricsPage(){return <><Heading title="Decisiones con datos de tus ventas" body={store?`Resumen de todo el historial de ${store.name}.`:'Resumen de todo el historial registrado. Los pedidos de ejemplo se identifican por tienda.'}/>{metricsCards()}<div className="two-column"><div className="panel"><div className="panel-title"><h3>Pedidos por estado</h3><span className="muted small">Todo el historial</span></div><div className="bars">{['Pendiente','Confirmado','Enviado','Entregado','Cancelado'].map(s=>{const n=allOrders.filter(o=>o.status===s).length;return <div className="bar-row" key={s}><span>{s}</span><div className="bar-track"><i style={{width:(allOrders.length?n/allOrders.length*100:0)+'%'}}/></div><b>{n}</b></div>})}</div></div><div className="panel"><div className="panel-title"><h3>Ventas cobradas por tienda</h3><Wallet size={19}/></div><div className="bars">{scope.length?scope.map(s=>{const v=s.orders.filter(o=>o.status!=='Cancelado'&&o.paymentStatus==='Pagado').reduce((a,o)=>a+o.total,0);return <div className="revenue-row" key={s.id}><span className={'store-avatar mini '+s.color}>{initials(s.name)}</span><span>{s.name}{s.demo&&<small>Ejemplo</small>}</span><b>{money(v)}</b></div>}):<p className="muted">Crea una tienda para empezar.</p>}</div></div></div><div className="inline-note"><BookOpen size={17}/>«Ventas cobradas» suma pedidos marcados como pagados y excluye cancelados. No incluye costos, comisiones ni utilidad. El estado de pago se registra manualmente.</div></>;}
 function settingsPage(){return <><Heading title="Tu espacio de trabajo" body="Controla los datos de tu negocio y revisa lo que está disponible."/><div className="settings-grid"><div className="panel"><div className="panel-title"><h3>{store?'Identidad de la tienda':'Configuración general'}</h3><Settings size={20}/></div><div className="settings-content">{store?<><div className="product-cell"><span className={'store-avatar '+store.color}>{initials(store.name)}</span><span><b>{store.name}</b><small>{store.category}</small></span></div><button className="btn secondary" onClick={()=>setModal({kind:'store',data:store})}>Editar tienda</button></>:<><h3>Un propietario, varias tiendas</h3><p>Tus datos están vinculados a tu cuenta. Puedes crear hasta 5 tiendas y cambiar entre ellas desde el menú lateral.</p><Badge tone="green"><ShieldCheck size={13}/> Acceso con tu cuenta de ChatGPT</Badge></>}<hr/><h4>Datos y respaldo</h4><p>Descarga una copia JSON del {store?'contenido de esta tienda':'espacio completo'}. Esta versión permite exportar; la importación aún no está disponible.</p><button className="btn secondary" onClick={exportData}><Download size={16}/>Exportar datos</button></div></div><div className="panel"><div className="panel-title"><h3>Estado de esta versión</h3><Badge tone="plum">Versión inicial</Badge></div><div className="readiness">{[['Tiendas, catálogo y clientes',true],['Pedidos y control de stock',true],['Configuración por tienda',true],['Guardado en el servidor',true],['WhatsApp e Instagram',false],['Respuestas con IA',false],['Cobro y conciliación automática',false],['Campañas y anuncios',false]].map(([n,v])=><div key={String(n)}><span>{n}</span><Badge tone={v?'green':'neutral'}>{v?'Disponible':'Pendiente'}</Badge></div>)}</div></div></div>{store&&<div className="panel modules-panel"><div className="panel-title"><div><h3>Módulos de la tienda</h3><p>Preferencias guardadas para próximas funciones. No activan automatizaciones todavía.</p></div></div>{[['wholesale','Ventas mayoristas','Precios por volumen y cantidades mínimas.'],['advisors','Equipo de asesores','Asignación de conversaciones entre colaboradores.']].map(([key,title,body])=><div className="module-row" key={key}><span className="icon-tile plum">{key==='wholesale'?<Package size={20}/>:<Users size={20}/>}</span><div><b>{title}</b><p>{body}</p></div><label className="toggle"><input type="checkbox" checked={store.modules[key as keyof typeof store.modules]} disabled={busy} onChange={e=>mutate('modules.save',{storeId:store.id,...store.modules,[key]:e.target.checked})}/><span/></label></div>)}</div>}</>;}
 function conversationsPage(){return <><Heading title="Conversaciones que se convierten en ventas" body="Aquí se reunirán los mensajes cuando conectemos los canales de cada tienda."/><div className="panel"><Empty icon={MessageCircle} title="Tu bandeja está lista para conectar" body="Todavía no hay mensajes reales. Puedes probar respuestas con el catálogo de una tienda sin enviar nada a tus clientes." action={()=>store?setModal({kind:'test'}):go('stores')} label={store?'Probar respuestas':'Seleccionar tienda'}/></div><div className="inline-note"><ShieldCheck size={17}/>El probador no crea conversaciones reales ni contacta a ninguna persona.</div></>;}
 async function handleSave(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);const d=Object.fromEntries(f.entries()) as any;const m=modal!;let type='',payload:any={storeId:store?.id,...d};
 if(m.kind==='store'){type=m.data?'store.update':'store.create';payload={...d,...(m.data?{storeId:m.data.id}:{})};}
 if(m.kind==='product'){type='product.save';payload={...payload,id:m.data?.id,price:Number(d.price),stock:Number(d.stock),active:d.active==='on'};}
 if(m.kind==='contact'){type='contact.save';payload={...payload,id:m.data?.id};}
 if(['faq','rule','promotion'].includes(m.kind)){type=m.kind+'.save';payload={...payload,id:m.data?.id,active:d.active==='on'};}
 if(m.kind==='order'){type='order.create';const rows=(Array.from(e.currentTarget.querySelectorAll('select[data-product]')) as any[]).map((el:any)=>({productId:el.value,quantity:Number((e.currentTarget.elements.namedItem('qty-'+el.dataset.product) as HTMLInputElement).value)})).filter(x=>x.productId);payload={storeId:store!.id,contactId:d.contactId,items:rows,channel:d.channel,notes:d.notes,paymentStatus:d.paymentStatus};}
 const w=await mutate(type,payload);if(w){setModal(null);if(m.kind==='store'&&!m.data){const id=w.stores[w.stores.length-1].id;openStore(id);}}}
 function ModalContent(){if(!modal)return null;const d=modal.data||{};
 if(modal.kind==='orderDetail'){const s=workspace.stores.find(s=>s.id===d.storeId)||store;const o=s?.orders.find(o=>o.id===d.id);if(!o)return <p>Pedido no encontrado.</p>;const transitions:Record<string,string[]>={Pendiente:['Confirmado','Cancelado'],Confirmado:['Enviado','Cancelado'],Enviado:['Entregado'],Entregado:[],Cancelado:[]};return <><ModalHeader title={o.number} sub={`${s!.name} · ${o.customer}`}/><div className="detail-body"><div className="spread"><Badge tone={statusTone(o.status)}>{o.status}</Badge><span className="muted small">{date(o.createdAt)} · {o.channel}</span></div>{o.items.map(l=><div className="order-line" key={l.productId}><div><b>{l.name}</b><small>{l.quantity} × {money(l.price)}</small></div><b>{money(l.price*l.quantity)}</b></div>)}<div className="order-total"><b>Total</b><strong>{money(o.total)}</strong></div><p className="muted">{o.notes||'Sin notas adicionales.'}</p><div className="inline-note">Stock reservado al registrar. Cancelar antes del envío repone las unidades. El estado de pago es manual.</div><div className="spread"><span>Pago: <Badge tone={statusTone(o.paymentStatus)}>{o.paymentStatus}</Badge></span>{o.status!=='Cancelado'&&<button className="text-button" disabled={busy} onClick={()=>mutate('order.payment',{storeId:s!.id,orderId:o.id,paymentStatus:o.paymentStatus==='Pagado'?'Pendiente':'Pagado'})}>{o.paymentStatus==='Pagado'?'Marcar pendiente':'Marcar pagado'}</button>}</div><div className="modal-actions">{transitions[o.status].map(v=><button key={v} disabled={busy} className={'btn '+(v==='Cancelado'?'danger':'primary')} onClick={()=>{if(v==='Cancelado'&&!confirm('¿Cancelar este pedido y devolver las unidades al stock?'))return;mutate('order.status',{storeId:s!.id,orderId:o.id,status:v});}}>{v==='Cancelado'?'Cancelar pedido':'Marcar '+v.toLowerCase()}</button>)}</div></div></>}
 if(modal.kind==='test')return <><ModalHeader title="Prueba tu vendedor" sub={`${store?.name} · simulación local por coincidencias`}/><div className="chat-warning"><TriangleAlert size={15}/>Sin IA conectada. No se envían mensajes reales.</div><div className="chat-messages">{!chat.length?<div className="chat-intro"><span className="agent-avatar"><Bot size={28}/></span><h3>{store?.agent.name}</h3><p>Prueba «Hola», «Ver catálogo», un nombre de producto o «Envíos».</p></div>:chat.map((m,i)=><div key={i} className={'chat-bubble '+m.role}>{m.text}</div>)}</div><div className="chat-suggestions">{['Hola','Ver catálogo','Envíos','Métodos de pago'].map(t=><button key={t} onClick={()=>{if(store)setChat([...chat,{role:'user',text:t},{role:'assistant',text:simulateReply(store,t)}]);}}>{t}</button>)}</div><form className="chat-input" onSubmit={e=>{e.preventDefault();if(message.trim()&&store){setChat([...chat,{role:'user',text:message},{role:'assistant',text:simulateReply(store,message)}]);setMessage('');}}}><input value={message} onChange={e=>setMessage(e.target.value)} placeholder="Escribe una consulta de prueba…" aria-label="Mensaje de prueba"/><button className="btn primary" aria-label="Probar mensaje" disabled={!message.trim()}><Send size={18}/></button></form></>;
 if(modal.kind==='channel')return <><ModalHeader title={`Preparar ${d.name}`} sub={store?store.name:'Conexión por tienda'}/><div className="detail-body"><span className={'channel-icon '+d.color}><Link2 size={26}/></span><h3>La integración está pendiente</h3><p>{d.needs}</p><div className="inline-note">Esta pantalla explica los requisitos. No inicia sesión en servicios externos ni crea una conexión.</div><button className="btn secondary" onClick={()=>setModal(null)}>Entendido</button></div></>;
 if(modal.kind==='integration')return <><ModalHeader title={d.name} sub="Próxima integración"/><div className="detail-body"><p>{d.desc}</p><p>El siguiente paso es elegir un proveedor, obtener acceso autorizado y conectar su servicio desde el servidor.</p><div className="inline-note">No introduzcas claves privadas en notas, prompts o campos del vendedor. Todavía no hay un formulario para credenciales.</div><button className="btn secondary" onClick={()=>setModal(null)}>Entendido</button></div></>;
 return <><ModalHeader title={{store:d.id?'Editar tienda':'Una nueva tienda, nuevas posibilidades',product:d.id?'Editar producto':'Añadir producto',contact:d.id?'Ficha del cliente':'Nuevo cliente',order:'Registrar pedido',faq:'Pregunta frecuente',rule:'Regla del vendedor',promotion:'Promoción'}[modal.kind]||'Editar'} sub={modal.kind==='store'?'Su propio catálogo, clientes y vendedor.':store?.name||''}/><form onSubmit={handleSave} className="edit-form">{modal.kind==='store'&&<><Field label="Nombre de la tienda" name="name" required maxLength={80} defaultValue={d.name} placeholder="Ej. Mi nueva marca"/><Field label="Categoría" name="category" required maxLength={80} defaultValue={d.category} placeholder="Ej. Moda y accesorios"/><label>Color de tu espacio<select name="color" defaultValue={d.color||'plum'}><option value="plum">Ciruela</option><option value="green">Salvia</option><option value="blue">Azul</option><option value="orange">Terracota</option></select></label><div className="inline-note"><Layers size={16}/>Los datos se guardan por separado de tus otras tiendas.</div></>}
 {modal.kind==='product'&&<><Field label="Nombre" name="name" required defaultValue={d.name} maxLength={120}/><div className="form-grid"><Field label="SKU" name="sku" defaultValue={d.sku} maxLength={60}/><Field label="Categoría" name="category" defaultValue={d.category} maxLength={80}/><Field label="Precio en soles (S/)" name="price" required type="number" min="0" max="10000000" step="0.01" defaultValue={d.price??0}/><Field label="Stock disponible" name="stock" required type="number" min="0" max="10000000" step="1" defaultValue={d.stock??0}/></div><label>Descripción<textarea name="description" maxLength={2000} defaultValue={d.description} rows={3}/></label><label className="checkbox-label"><input type="checkbox" name="active" defaultChecked={d.active??true}/>Producto activo en el catálogo</label></>}
 {modal.kind==='contact'&&<><Field label="Nombre completo" name="name" required maxLength={120} defaultValue={d.name}/><div className="form-grid"><Field label="Teléfono" name="phone" type="tel" maxLength={30} defaultValue={d.phone} placeholder="+51…"/><Field label="Email" name="email" type="email" defaultValue={d.email}/></div><label>Etapa<select name="stage" defaultValue={d.stage||'Nuevo'}>{['Nuevo','En conversación','Cliente','Inactivo'].map(v=><option key={v}>{v}</option>)}</select></label><label>Notas<textarea name="notes" maxLength={2000} defaultValue={d.notes} rows={3}/></label></>}
 {['faq','rule','promotion'].includes(modal.kind)&&<><Field label={modal.kind==='faq'?'Pregunta':'Nombre'} name="title" required maxLength={200} defaultValue={d.title}/><label>{modal.kind==='faq'?'Respuesta':'Contenido'}<textarea name="content" required maxLength={4000} defaultValue={d.content} rows={5}/></label><label className="checkbox-label"><input type="checkbox" name="active" defaultChecked={d.active??true}/>Activo</label>{modal.kind==='promotion'&&<div className="inline-note">Referencia informativa. No modifica precios ni aplica descuentos a los pedidos.</div>}</>}
 {modal.kind==='order'&&<OrderFields store={store!}/>}
 <div className="modal-actions"><button type="button" className="btn secondary" onClick={()=>setModal(null)}>Cancelar</button><button className="btn primary" disabled={busy||(modal.kind==='order'&&(!store?.contacts.length||!store?.products.some(p=>p.active&&p.stock>0)))}>{busy?'Guardando…':modal.kind==='order'?'Registrar y reservar stock':'Guardar'}</button></div></form></>;
 }
 function ModalHeader({title,sub}:{title:string;sub:string}){return <div className="modal-header"><div><h2>{title}</h2><p>{sub}</p></div><button className="icon-button" type="button" onClick={()=>setModal(null)} aria-label="Cerrar"><X size={20}/></button></div>}
 const titles={overview,stores:storesPage,dashboard,products:productsPage,contacts:contactsPage,orders:ordersPage,agent:agentPage,channels:channelsPage,conversations:conversationsPage,promotions:()=>storeRequired(()=>entryList('promotion',store!.promotions)),integrations:integrationsPage,metrics:metricsPage,settings:settingsPage};
 return <div className={'app-shell glass-theme '+(navExpanded?'nav-expanded ':'')+(solidMode?'solid-mode':'')}>{mobile&&<button className="mobile-backdrop" onClick={()=>setMobile(false)} aria-label="Cerrar menú"/>}<aside className={'sidebar '+(mobile?'open':'')}><a href="/" className="brand" onClick={e=>{e.preventDefault();setSelected(null);go('overview');}}><span className="brand-mark">n</span><span className="brand-word">nexo</span><span className="brand-caption">VENTAS</span></a><div className="workspace-label">TU ESPACIO DE TRABAJO</div><div className="store-switch-wrap"><button title={store?.name||'Cambiar de tienda'} className="store-switch" onClick={()=>setStoreDropdown(!storeDropdown)} aria-expanded={storeDropdown}><span className={'store-avatar mini '+(store?.color||'plum')}>{store?initials(store.name):<Layers size={17}/>}</span><span><b>{store?.name||'Todas mis tiendas'}</b><small>{store?'Espacio independiente':`${allStores.length} tiendas en tu cuenta`}</small></span><ChevronDown size={16}/></button>{storeDropdown&&<div className="store-dropdown"><button onClick={()=>{setSelected(null);go('overview');setStoreDropdown(false);}}><Layers size={15}/>Todas mis tiendas</button>{allStores.map(s=><button key={s.id} onClick={()=>openStore(s.id)}><span className={'color-dot '+s.color}/>{s.name}{s.demo&&<small>Ejemplo</small>}</button>)}<button className="add" onClick={()=>{setStoreDropdown(false);requestNewStore();}}><Plus size={15}/>Nueva tienda</button></div>}</div><button title="Buscar una sección" className="nav-search" onClick={()=>setMenuOpen(true)}><Search size={15}/><span className="nav-copy">Ir a una sección</span><kbd>⌘ K</kbd></button><nav><div className="nav-label">GENERAL</div><button title="Vista general" className={!store&&page==='overview'?'active':''} onClick={()=>{setSelected(null);go('overview');}}><LayoutGrid size={18}/><span className="nav-copy">Vista general</span></button><button title="Mis tiendas" className={page==='stores'?'active':''} onClick={()=>{setSelected(null);go('stores');}}><StoreIcon size={18}/><span className="nav-copy">Mis tiendas</span><span className="nav-count">{allStores.length}</span></button><div className="nav-label">{store?'GESTIONAR TIENDA':'GESTIÓN COMERCIAL'}</div>{nav.filter(n=>store||!['dashboard','products','promotions','agent','contacts'].includes(n.id)).map(n=><button title={n.name} key={n.id} className={page===n.id?'active':''} onClick={()=>go(n.id as Page)}><n.icon size={18}/><span className="nav-copy">{n.name}</span>{n.id==='channels'&&<span className="nav-dot"/>}</button>)}</nav><div className="sidebar-bottom"><button title="Configuración" className={page==='settings'?'active':''} onClick={()=>go('settings')}><Settings size={18}/><span className="nav-copy">Configuración</span></button><button title="Guía de inicio" onClick={()=>setModal({kind:'help'})}><LifeBuoy size={18}/><span className="nav-copy">Guía de inicio</span></button><button title={solidMode?'Activar transparencias':'Reducir transparencias'} onClick={toggleSurface}><Sparkles size={18}/><span className="nav-copy">{solidMode?'Modo cristal':'Mayor contraste'}</span></button><div className="profile"><span className="profile-avatar">{initials(userName)}</span><div><b>{userName}</b><small>Miembro del espacio</small></div><ShieldCheck size={15}/></div></div></aside><div className="main-shell"><header className="topbar"><div className="breadcrumb"><button className="icon-button desktop-nav-toggle" title={navExpanded?'Contraer menú':'Expandir menú'} onClick={()=>setNavExpanded(!navExpanded)}><Menu size={18}/></button><button className="icon-button mobile-menu" onClick={()=>setMobile(true)} aria-label="Abrir menú"><Menu size={20}/></button><span>{store?.name||'Mi espacio'}</span><ChevronRight size={13}/><b>{names[page]}</b></div><div className="topbar-actions"><span className="private-label"><ShieldCheck size={14}/>Espacio privado</span><button className="icon-button" title="Actualizar datos" disabled={loading||busy} onClick={load}><RefreshCw size={17}/></button><button className="btn small-btn secondary" onClick={exportData}><Download size={14}/><span>Exportar</span></button><span className="profile-avatar small-avatar">{initials(userName)}</span></div></header><main><div className="version-banner"><span><i/>Versión inicial <span className="banner-separator">/</span> Gestión disponible · Canales e IA pendientes</span><button onClick={()=>go('settings')}>Ver estado <ArrowUpRight size={13}/></button></div><div className={'workspace-layout '+(['overview','dashboard'].includes(page)?'with-rail':'')}><div className="workspace-body">{loading?<div className="loading"><span className="spinner"/>Cargando tus tiendas…</div>:failure?<Empty icon={TriangleAlert} title="No pudimos cargar tu espacio" body={failure} action={load} label="Volver a intentar"/>:titles[page]()}</div>{!loading&&!failure&&['overview','dashboard'].includes(page)&&<OperationsRail name={userName} stores={allStores.length} products={productCount} orders={allOrders} onOrder={o=>setModal({kind:'orderDetail',data:o})} onCreate={()=>requestNewStore()} onStores={()=>{setSelected(null);go('stores');}}/>}</div><footer>Nexo · Tu negocio, en un solo lugar.<span><a href="https://unsplash.com/photos/uF8WQrocMSE" target="_blank" rel="noreferrer">Fondo: EZcurtain Life / Unsplash</a></span></footer></main></div>{notice&&<div className="toast" role="status"><CheckCircle2 size={18}/>{notice}<button onClick={()=>setNotice('')} aria-label="Cerrar aviso"><X size={15}/></button></div>}{modal&&<ModalShell onClose={()=>setModal(null)}>{modal.kind==='help'?<><ModalHeader title="Empieza con Nexo" sub="Tu centro privado para varias tiendas"/><div className="detail-body"><ol className="help-list"><li>Crea una tienda para cada marca.</li><li>Añade sus productos con precio y stock.</li><li>Registra clientes y crea pedidos.</li><li>Configura el vendedor y prueba respuestas.</li><li>Revisa los requisitos antes de conectar canales.</li></ol><div className="inline-note">Los pedidos se registran manualmente. Esta versión no cobra ni envía mensajes. Todas las tiendas usan soles (PEN).</div><button className="btn primary" onClick={()=>{setModal(null);go('stores');}}>Ver mis tiendas <ArrowRight size={16}/></button></div></> : ModalContent()}</ModalShell>}{menuOpen&&<ModalShell onClose={()=>setMenuOpen(false)}><div className="modal-header"><h2>Ir a una sección</h2><button className="icon-button" onClick={()=>setMenuOpen(false)} aria-label="Cerrar"><X size={20}/></button></div><div className="command-list">{Object.entries(names).filter(([v])=>store||!['dashboard','products','contacts','agent','promotions'].includes(v)).map(([v,n])=><button key={v} onClick={()=>go(v as Page)}>{n}<ArrowRight size={16}/></button>)}</div></ModalShell>}</div>;
}
function Field({label,...props}:any){return <label>{label}<input {...props}/></label>}
function ModalShell({children,onClose}:{children:React.ReactNode;onClose:()=>void}){const ref=useRef<HTMLDivElement>(null);useEffect(()=>{const before=document.activeElement as HTMLElement;const old=document.body.style.overflow;document.body.style.overflow='hidden';ref.current?.focus();function trap(e:KeyboardEvent){if(e.key!=='Tab')return;const a=Array.from(ref.current?.querySelectorAll<HTMLElement>('button:not([disabled]),a,input:not([disabled]),select,textarea,[tabindex="0"]')||[]);const first=a[0],last=a[a.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}document.addEventListener('keydown',trap);return()=>{document.body.style.overflow=old;document.removeEventListener('keydown',trap);before?.focus();};},[]);return <div className="modal-overlay" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><div className="modal" role="dialog" aria-modal="true" aria-label="Formulario de Nexo" tabIndex={-1} ref={ref}>{children}</div></div>}
function AgentForm({store,tab,busy,onSave}:{store:Store;tab:string;busy:boolean;onSave:(a:Agent)=>Promise<void>}){const a=store.agent;return <form className="panel agent-form" onSubmit={async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget).entries());await onSave({...a,...f} as Agent);}}><div className="panel-title"><div><h3>{tab==='personalidad'?'El estilo de tu vendedor':tab==='negocio'?'Lo que debe saber de tu negocio':'Políticas claras, clientes tranquilos'}</h3><p>Esta configuración pertenece únicamente a {store.name}.</p></div><span className="icon-tile plum"><Bot size={20}/></span></div><div className="settings-content">{tab==='personalidad'&&<><div className="form-grid"><Field label="Nombre del vendedor" name="name" required maxLength={80} defaultValue={a.name}/><label>Tono de comunicación<select name="tone" defaultValue={a.tone}>{['Cercano','Profesional','Entusiasta'].map(v=><option key={v}>{v}</option>)}</select></label></div><label>Mensaje de bienvenida<textarea name="greeting" defaultValue={a.greeting} maxLength={1000} rows={3}/></label><label>Instrucciones de atención<textarea name="instructions" defaultValue={a.instructions} maxLength={8000} rows={5}/></label></>}{tab==='negocio'&&<label>Descripción del negocio<textarea name="description" defaultValue={a.description} maxLength={4000} rows={8} placeholder="Qué vendes, a quién ayudas y qué diferencia a tu marca…"/></label>}{tab==='politicas'&&<><label>Envíos y plazos<textarea name="shipping" maxLength={3000} defaultValue={a.shipping} rows={3} placeholder="Cobertura, costos y tiempos de entrega…"/></label><label>Métodos de pago<textarea name="payments" maxLength={3000} defaultValue={a.payments} rows={3} placeholder="Métodos aceptados e indicaciones para confirmar el pago…"/></label><label>Cambios y devoluciones<textarea name="returns" maxLength={3000} defaultValue={a.returns} rows={3}/></label></>}<div className="form-actions"><span className="muted small"><ShieldCheck size={14}/> Configuración privada de tu tienda</span><button className="btn primary" disabled={busy}>{busy?'Guardando…':'Guardar cambios'}<Check size={16}/></button></div></div></form>}
function OrderFields({store}:{store:Store}){const [count,setCount]=useState(1);const [values,setValues]=useState<Record<number,{id:string;q:number}>>({});const available=store.products.filter(p=>p.active&&p.stock>0);const total=Object.values(values).reduce((a,v)=>a+(store.products.find(p=>p.id===v.id)?.price||0)*v.q,0);return <><div className="inline-note">Provincias fuera de Lima: adelanto del 50% del valor de los productos, envío por Shalom y saldo posterior. Lima: opción de pago al recibir con el motorizado. El momento de cobro del saldo y el costo del envío se confirman con la tienda. Un adelanto no equivale a un pago completo.</div><div className="inline-note">Al guardar se descuenta el stock. No se realizará un cobro ni se enviará una confirmación al cliente.</div>{!store.contacts.length||!available.length?<div className="inline-note orange">Primero añade al menos un cliente y un producto activo con stock.</div>:null}<label>Cliente<select name="contactId" required defaultValue=""><option value="" disabled>Selecciona un cliente</option>{store.contacts.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><div className="order-products"><b>Productos</b>{Array.from({length:count},(_,i)=><div className="order-product-row" key={i}><select data-product={i} aria-label={'Producto '+(i+1)} required={i===0} defaultValue="" onChange={e=>setValues({...values,[i]:{id:e.target.value,q:values[i]?.q||1}})}><option value="">{i?'Sin producto adicional':'Selecciona un producto'}</option>{available.map(p=><option key={p.id} value={p.id}>{p.name} · {money(p.price)} · {p.stock} u.</option>)}</select><input name={'qty-'+i} type="number" aria-label={'Cantidad '+(i+1)} defaultValue={1} required min={1} step={1} max={10000} onChange={e=>setValues({...values,[i]:{id:values[i]?.id||'',q:Number(e.target.value)}})}/></div>)}<button type="button" className="text-button" disabled={count>=20} onClick={()=>setCount(count+1)}><Plus size={15}/>Añadir otra línea</button></div><div className="form-grid"><label>Origen del pedido<select name="channel"><option>Manual</option><option>WhatsApp</option><option>Instagram</option><option>Web</option></select></label><label>Pago registrado manualmente<select name="paymentStatus"><option>Pendiente</option><option>Pagado</option></select></label></div><label>Notas<textarea name="notes" maxLength={2000} rows={2}/></label><div className="order-total"><span>Total de productos</span><strong>{money(total)}</strong></div></>}
